  const defs = workflow.definitions ?? [];
  const connectorKey = getContextValue(getModelContext(node, defs), "connectorKey");
  if (connectionId && connectorKey) {
    await createConnectionResourceFile(fs, filePath, connectionId, connectorKey);
  }
